        'month' => [1, 'year'],
        'day' => [1, 'month'],
        'hour' => [0, 'day'],
        'minute' => [0, 'hour'],
        'second' => [0, 'minute'],
        'microsecond' => [0, 'second'],
    ];

    foreach ($units as $unit => [$minimum, $startUnit]) {
        if ($minimum === $median->$unit) {
            $current = $current->startOf($startUnit);

            break;
        }
